import java.io.*;

public class Main {
    static byte[] buf;
    static int bp;

    static long nextLong() {
        while (buf[bp] <= ' ') bp++;
        long r = 0;
        while (bp < buf.length && buf[bp] > ' ') r = r * 10 + (buf[bp++] - '0');
        return r;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = (int) nextLong();
        long prev = nextLong(), profit = prev;  // sell the initial unit on day 0
        for (int i = 1; i < n; i++) {
            long x = nextLong();
            if (x > prev) profit += x - prev;
            prev = x;
        }
        System.out.println(profit % 1_000_000_000L);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	next := func() int64 { sc.Scan(); v, _ := strconv.ParseInt(sc.Text(), 10, 64); return v }
	n := int(next())
	prev := next()
	profit := prev // sell the initial unit on day 0
	for i := 1; i < n; i++ {
		x := next()
		if x > prev {
			profit += x - prev
		}
		prev = x
	}
	fmt.Println(profit % 1_000_000_000)
}
